import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ViewMode {
  PLAYER = 'PLAYER',
  ADMIN = 'ADMIN',
  SETUP = 'SETUP'
}

export interface Question {
  id: number;
  text: string;
  a: string;
  b: string;
  c: string;
  d: string;
  correct: string;
}

export interface GameStatus {
  currentQuestionId: number;
  isVotingOpen: boolean;
  showAnswer: boolean;
  playerAnswers: (string | null)[]; // 8 players
}

export interface GasResponse {
  success: boolean;
  data?: any;
  error?: string;
}

import React, { useState, useEffect } from 'react';
import { ViewMode } from './types';
import PlayerView from './components/PlayerView';
import AdminView from './components/AdminView';
import SetupView from './components/SetupView';
import Header from './components/Header';

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>(ViewMode.SETUP);
  const [scriptUrl, setScriptUrl] = useState<string>(localStorage.getItem('gas_url') || '');
  const [playerId, setPlayerId] = useState<number | null>(null);

  useEffect(() => {
    if (scriptUrl) {
      localStorage.setItem('gas_url', scriptUrl);
    }
  }, [scriptUrl]);

  const handleSetup = (url: string, mode: ViewMode, id?: number) => {
    setScriptUrl(url);
    setView(mode);
    if (id !== undefined) setPlayerId(id);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header currentView={view} onBack={() => setView(ViewMode.SETUP)} />

      <main className="flex-grow container mx-auto px-4 py-8">
        {view === ViewMode.SETUP && (
          <SetupView onComplete={handleSetup} initialUrl={scriptUrl} />
        )}

        {view === ViewMode.PLAYER && playerId !== null && (
          <PlayerView scriptUrl={scriptUrl} playerId={playerId} />
        )}

        {view === ViewMode.ADMIN && (
          <AdminView scriptUrl={scriptUrl} />
        )}
      </main>

      <footer className="bg-slate-900 py-4 text-center text-slate-500 text-sm border-t border-slate-800">
        نظام Quiz Master vMix Pro &copy; {new Date().getFullYear()}
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { ViewMode } from '../types';

interface HeaderProps {
  currentView: ViewMode;
  onBack: () => void;
}

const Header: React.FC<HeaderProps> = ({ currentView, onBack }) => {
  return (
    <header className="bg-slate-900 border-b border-slate-800 p-4 shadow-xl">
      <div className="container mx-auto flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <span className="text-xl font-bold">Q</span>
          </div>
          <h1 className="text-2xl font-black bg-clip-text text-transparent bg-gradient-to-l from-indigo-400 to-cyan-400 tracking-tight">
            QUIZ MASTER <span className="text-sm font-normal text-slate-400">vMix Edition</span>
          </h1>
        </div>

        {currentView !== ViewMode.SETUP && (
          <button 
