export default SetupView;

import React, { useState, useEffect, useCallback } from 'react';
import { GameStatus, Question } from '../types';

interface PlayerViewProps {
  scriptUrl: string;
  playerId: number;
}

const PlayerView: React.FC<PlayerViewProps> = ({ scriptUrl, playerId }) => {
  const [status, setStatus] = useState<GameStatus | null>(null);
  const [question, setQuestion] = useState<Question | null>(null);
  const [myAnswer, setMyAnswer] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchStatus = useCallback(async () => {
    try {
      const resp = await fetch(`${scriptUrl}?action=getStatus`);
      const data = await resp.json();
      if (data.success) {
        setStatus(data.data.status);
        setQuestion(data.data.question);

        // Reset local answer if question changed
        if (data.data.status.currentQuestionId !== status?.currentQuestionId) {
          setMyAnswer(null);
        }
      }
    } catch (e) {
      console.error("Polling error:", e);
    }
  }, [scriptUrl, status?.currentQuestionId]);

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 500); // Polling every 0.5s
    return () => clearInterval(interval);
  }, [fetchStatus]);

  const submitAnswer = async (answer: string) => {
    if (!status?.isVotingOpen || isSubmitting) return;

    setIsSubmitting(true);
    setMyAnswer(answer);

    try {
      const resp = await fetch(`${scriptUrl}?action=submitAnswer&playerId=${playerId}&answer=${answer}`);
      const data = await resp.json();
      if (!data.success) setError("فشل في إرسال الإجابة");
    } catch (e) {
      setError("حدث خطأ في الاتصال");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!status || !question) {
    return (
      <div className="flex flex-col items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500 mb-4"></div>
        <p className="text-slate-400">جاري الاتصال بالنظام...</p>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-top-4 duration-500">
      <div className="flex justify-between items-center mb-6">
        <div className="bg-slate-800 px-4 py-2 rounded-lg border border-slate-700">
          <span className="text-slate-400 text-sm">أنت المتسابق</span>
          <div className="text-2xl font-bold text-indigo-400">#{playerId}</div>
        </div>
        <div className={`px-4 py-2 rounded-lg font-bold border ${status.isVotingOpen ? 'bg-emerald-900/30 text-emerald-400 border-emerald-800' : 'bg-rose-900/30 text-rose-400 border-rose-800'}`}>
          {status.isVotingOpen ? '● التصويت مفتوح' : '○ التصويت مغلق'}
        </div>
      </div>

      <div className="bg-slate-800/50 p-8 rounded-3xl border border-slate-700 shadow-2xl mb-8 text-center">
        <span className="text-indigo-500 font-bold mb-2 block tracking-widest uppercase">السؤال رقم {status.currentQuestionId}</span>
        <h3 className="text-2xl md:text-3xl font-bold leading-tight">{question.text}</h3>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {['A', 'B', 'C', 'D'].map((key) => {
          const optionText = question[key.toLowerCase() as keyof Question];
          const isSelected = myAnswer === key;

          return (
            <button
              key={key}
              disabled={!status.isVotingOpen || isSubmitting}
              onClick={() => submitAnswer(key)}
              className={`
                group relative flex items-center p-6 rounded-2xl border-2 transition-all duration-200 text-right
                ${!status.isVotingOpen ? 'opacity-60 grayscale cursor-not-allowed' : 'hover:scale-[1.02] active:scale-95'}
                ${isSelected 
                  ? 'bg-indigo-600 border-indigo-400 shadow-lg shadow-indigo-900/50' 
                  : 'bg-slate-800 border-slate-700 hover:border-slate-500'}
              `}
            >
              <div className={`
                flex items-center justify-center w-12 h-12 rounded-xl font-black text-xl ml-4
                ${isSelected ? 'bg-white text-indigo-600' : 'bg-slate-700 text-slate-300 group-hover:bg-slate-600'}
              `}>
                {key}
              </div>
              <div className="flex-grow text-lg font-bold">
                {optionText}
              </div>
              {isSelected && (
                <div className="absolute top-2 left-2 bg-white rounded-full p-1">
                  <svg className="w-4 h-4 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                </div>
              )}
            </button>
          );
        })}
      </div>

      {error && (
        <div className="mt-6 p-4 bg-rose-500/20 border border-rose-500 rounded-xl text-rose-300 text-center">
          {error}
        </div>
      )}
    </div>
  );
};

export default PlayerView;

import React, { useState, useEffect, useCallback } from 'react';
import { GameStatus, Question } from '../types';

interface AdminViewProps {
  scriptUrl: string;
}

const AdminView: React.FC<AdminViewProps> = ({ scriptUrl }) => {
  const [status, setStatus] = useState<GameStatus | null>(null);
  const [question, setQuestion] = useState<Question | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const fetchStatus = useCallback(async () => {
    try {
      const resp = await fetch(`${scriptUrl}?action=getStatus`);
      const data = await resp.json();
      if (data.success) {
        setStatus(data.data.status);
        setQuestion(data.data.question);
      }
    } catch (e) {
      console.error("Polling error:", e);
    }
  }, [scriptUrl]);

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 1000);
    return () => clearInterval(interval);
  }, [fetchStatus]);

  const runAction = async (action: string) => {
    setIsLoading(true);
    try {
      await fetch(`${scriptUrl}?action=${action}`);
      await fetchStatus();
    } catch (e) {
      alert("حدث خطأ في تنفيذ العملية");
    } finally {
      setIsLoading(false);
    }
  };

  if (!status || !question) return <div className="text-center p-10">جاري التحميل...</div>;

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      {/* Control Panel */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="col-span-1 md:col-span-2 bg-slate-800 p-8 rounded-3xl border border-slate-700 shadow-2xl">
          <h3 className="text-indigo-400 font-bold mb-4 uppercase text-sm tracking-widest">تحكم المضيف</h3>
          <div className="flex flex-wrap gap-4">
            <button 
              disabled={isLoading}
              onClick={() => runAction('nextQuestion')}
              className="flex-grow py-4 px-6 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 rounded-2xl font-black text-xl shadow-lg transition-all active:scale-95 disabled:opacity-50"
            >
              السؤال التالي
            </button>
            <button 
              disabled={isLoading}
              onClick={() => runAction('toggleVoting')}
              className={`flex-grow py-4 px-6 rounded-2xl font-black text-xl shadow-lg transition-all active:scale-95 disabled:opacity-50 ${status.isVotingOpen ? 'bg-rose-600' : 'bg-emerald-600'}`}
            >
              {status.isVotingOpen ? 'إغلاق التصويت' : 'فتح التصويت'}
            </button>
            <button 
              disabled={isLoading}
              onClick={() => runAction('toggleAnswer')}
              className="w-full py-4 px-6 bg-slate-700 hover:bg-slate-600 rounded-2xl font-black text-xl shadow-lg transition-all active:scale-95 border border-slate-600"
            >
              {status.showAnswer ? 'إخفاء الإجابة' : 'إظهار الإجابة الصحيحة'}
            </button>
          </div>
        </div>

        <div className="bg-slate-900 border border-indigo-900/40 p-6 rounded-3xl flex flex-col items-center justify-center text-center">
          <span className="text-slate-400 text-sm mb-1 uppercase">السؤال الحالي</span>
          <div className="text-6xl font-black text-white">{status.currentQuestionId}</div>
          <div className="mt-4 px-4 py-1 bg-indigo-500/20 text-indigo-400 rounded-full text-sm font-bold border border-indigo-500/30">
            vMix Active
          </div>
        </div>
      </div>

      {/* Players Status Grid */}
      <div className="bg-slate-800 p-8 rounded-3xl border border-slate-700 shadow-2xl">
        <h3 className="text-slate-400 font-bold mb-6 uppercase text-sm tracking-widest">إجابات المتسابقين (الربط المباشر مع vMix)</h3>
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-4">
          {status.playerAnswers.map((ans, idx) => (
            <div key={idx} className="flex flex-col items-center space-y-2">
              <div className={`
                w-12 h-12 flex items-center justify-center rounded-2xl font-black text-2xl transition-all shadow-md
                ${ans ? 'bg-emerald-500 text-white animate-bounce' : 'bg-slate-700 text-slate-500 border border-slate-600'}
              `}>
                {ans || '-'}
              </div>
              <span className="text-xs font-bold text-slate-500">متسابق {idx + 1}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Question Details */}
      <div className="bg-slate-800/50 p-6 rounded-3xl border border-slate-700 flex gap-6 items-center">
        <div className="flex-grow">
          <p className="text-slate-500 text-sm mb-1">محتوى السؤال الحالي:</p>
          <p className="text-xl font-bold">{question.text}</p>
        </div>
        <div className="text-right">
          <p className="text-slate-500 text-sm mb-1">الإجابة الصحيحة:</p>
          <p className="text-3xl font-black text-emerald-400">{question.correct}</p>
        </div>
      </div>
    </div>
  );
};

export default AdminView;

/**
 * هذا الكود يوضع في Google Apps Script
 * قم بإنشاء ملف جديد باسم Code.gs والصق هذا الكود فيه
 * ثم اضغط Deploy -> New Deployment -> Web App
 * تأكد من اختيار Anyone للوصول.
 */

const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();

function doGet(e) {
  const action = e.parameter.action;
  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const statusSheet = ss.getSheetByName('Status');
  const questionsSheet = ss.getSheetByName('Questions');

  // Headers check (Initialization)
  if (statusSheet.getLastRow() === 0) {
    statusSheet.appendRow(['QuestionID', 'VotingOpen', 'ShowAnswer', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8']);
    statusSheet.appendRow([1, 'FALSE', 'FALSE', '', '', '', '', '', '', '', '']);
  }

  let result = { success: true };

  try {
    switch(action) {
      case 'getStatus':
        const statusData = statusSheet.getRange(2, 1, 1, 11).getValues()[0];
        const qId = parseInt(statusData[0]);

        // Find question
        const allQuestions = questionsSheet.getDataRange().getValues();
        let questionObj = null;
        if (allQuestions.length > qId) {
          const row = allQuestions[qId]; // Assuming first row is header, index matches ID
          questionObj = {
            id: qId,
            text: row[0],
            a: row[1],
            b: row[2],
            c: row[3],
            d: row[4],
            correct: row[5]
          };
        }

        result.data = {
          status: {
            currentQuestionId: qId,
            isVotingOpen: statusData[1] === true || statusData[1] === 'TRUE',
            showAnswer: statusData[2] === true || statusData[2] === 'TRUE',
            playerAnswers: statusData.slice(3)
          },
          question: questionObj
        };
        break;

      case 'submitAnswer':
        const pId = parseInt(e.parameter.playerId);
        const ans = e.parameter.answer;
        const currentOpen = statusSheet.getRange(2, 2).getValue();
        if (currentOpen === true || currentOpen === 'TRUE') {
          statusSheet.getRange(2, 3 + pId).setValue(ans);
        } else {
          result.success = false;
          result.error = "Voting is closed";
        }
        break;

      case 'nextQuestion':
        const currentId = statusSheet.getRange(2, 1).getValue();
        statusSheet.getRange(2, 1).setValue(parseInt(currentId) + 1);
        statusSheet.getRange(2, 2).setValue('TRUE'); // Open voting
        statusSheet.getRange(2, 3).setValue('FALSE'); // Hide answer
        statusSheet.getRange(2, 4, 1, 8).clearContent(); // Clear answers
        break;

      case 'toggleVoting':
        const currentV = statusSheet.getRange(2, 2).getValue();
        statusSheet.getRange(2, 2).setValue(!(currentV === true || currentV === 'TRUE'));
        break;

      case 'toggleAnswer':
        const currentA = statusSheet.getRange(2, 3).getValue();
        statusSheet.getRange(2, 3).setValue(!(currentA === true || currentA === 'TRUE'));
        break;
    }
  } catch (err) {
    result.success = false;
    result.error = err.toString();
  }

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

/**
 * كود Google Apps Script المحدث
 * يدعم السؤال السابق ومؤقت الـ 20 ثانية المتزامن.
 */

const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();

function doGet(e) {
  const action = e.parameter.action;
  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const statusSheet = ss.getSheetByName('Status');
  const questionsSheet = ss.getSheetByName('Questions');

  // تهيئة الأعمدة إذا كانت الورقة فارغة
  if (statusSheet.getLastRow() === 0) {
    statusSheet.appendRow(['QuestionID', 'VotingOpen', 'ShowAnswer', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8', 'TimerEnd']);
    statusSheet.appendRow([1, 'FALSE', 'FALSE', '', '', '', '', '', '', '', '', '0']);
  }

  let result = { success: true };

  try {
    switch(action) {
      case 'getStatus':
        const statusData = statusSheet.getRange(2, 1, 1, 12).getValues()[0];
        const qId = parseInt(statusData[0]);

        const allQuestions = questionsSheet.getDataRange().getValues();
        let questionObj = null;
        if (allQuestions.length > qId) {
          const row = allQuestions[qId];
          questionObj = {
            id: qId,
            text: row[0], a: row[1], b: row[2], c: row[3], d: row[4], correct: row[5]
          };
        }

        result.data = {
          status: {
            currentQuestionId: qId,
            isVotingOpen: statusData[1] === true || statusData[1] === 'TRUE',
            showAnswer: statusData[2] === true || statusData[2] === 'TRUE',
            playerAnswers: statusData.slice(3, 11),
            timerEnd: parseFloat(statusData[11]) || 0
          },
          question: questionObj
        };
        break;

      case 'submitAnswer':
        const pId = parseInt(e.parameter.playerId);
        const ans = e.parameter.answer;
        const currentOpen = statusSheet.getRange(2, 2).getValue();
        if (currentOpen === true || currentOpen === 'TRUE') {
          statusSheet.getRange(2, 3 + pId).setValue(ans);
        } else {
          result.success = false;
          result.error = "التصويت مغلق حالياً";
        }
        break;

      case 'nextQuestion':
        updateQuestion(statusSheet, 1);
        break;

      case 'prevQuestion':
        updateQuestion(statusSheet, -1);
        break;

      case 'toggleVoting':
        const currentV = statusSheet.getRange(2, 2).getValue();
        const newState = !(currentV === true || currentV === 'TRUE');
        statusSheet.getRange(2, 2).setValue(newState);
        if (newState) {
          // إذا تم فتح التصويت، ابدأ مؤقت 20 ثانية من الآن
          const endTime = new Date().getTime() + 20000;
          statusSheet.getRange(2, 12).setValue(endTime.toString());
        }
        break;

      case 'toggleAnswer':
        const currentA = statusSheet.getRange(2, 3).getValue();
        statusSheet.getRange(2, 3).setValue(!(currentA === true || currentA === 'TRUE'));
        break;
    }
  } catch (err) {
    result.success = false;
    result.error = err.toString();
  }

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function updateQuestion(sheet, delta) {
  const currentId = parseInt(sheet.getRange(2, 1).getValue());
