const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();

function doGet(e) {
  const action = e.parameter.action;
  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const statusSheet = ss.getSheetByName('Status');
  const questionsSheet = ss.getSheetByName('Questions');

  // تهيئة الأعمدة إذا كانت الورقة فارغة
  if (statusSheet.getLastRow() === 0) {
    statusSheet.appendRow(['QuestionID', 'VotingOpen', 'ShowAnswer', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8', 'TimerEnd']);
    statusSheet.appendRow([1, 'FALSE', 'FALSE', '', '', '', '', '', '', '', '', '0']);
  }

  let result = { success: true };

  try {
    switch(action) {
      case 'getStatus':
        let statusData = statusSheet.getRange(2, 1, 1, 12).getValues()[0];
        let qId = parseInt(statusData[0]);
        let isVotingOpen = String(statusData[1]).toUpperCase() === 'TRUE';
        let timerEnd = parseFloat(statusData[11]) || 0;
        const now = new Date().getTime();

        // منطق الإغلاق التلقائي: إذا انتهى الوقت والتصويت لا يزال مفتوحاً
        if (isVotingOpen && timerEnd > 0 && now >= timerEnd) {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue('0');
          isVotingOpen = false; // تحديث الحالة للإرسال في الرد الحالي
          timerEnd = 0;
          statusData[1] = 'FALSE'; // تحديث البيانات المحلية للرد
          statusData[11] = '0';
        }

        const allQuestions = questionsSheet.getDataRange().getValues();
        let questionObj = null;
        if (allQuestions.length > qId) {
          const row = allQuestions[qId];
          questionObj = {
            id: qId,
            text: row[0], a: row[1], b: row[2], c: row[3], d: row[4], correct: row[5]
          };
        }

        result.data = {
          status: {
            currentQuestionId: qId,
            isVotingOpen: isVotingOpen,
            showAnswer: String(statusData[2]).toUpperCase() === 'TRUE',
            playerAnswers: statusData.slice(3, 11).map(a => a === null || a === undefined ? "" : String(a)),
            timerEnd: timerEnd
          },
          question: questionObj
        };
        break;

      case 'submitAnswer':
        const pId = parseInt(e.parameter.playerId);
        const ans = String(e.parameter.answer).toUpperCase();

        // إعادة فحص الحالة للتأكد من عدم انتهاء الوقت أثناء الطلب
        const currentStatusRow = statusSheet.getRange(2, 1, 1, 12).getValues()[0];
        const vOpen = String(currentStatusRow[1]).toUpperCase() === 'TRUE';
        const tEnd = parseFloat(currentStatusRow[11]) || 0;
        const tNow = new Date().getTime();

        if (!vOpen || (tEnd > 0 && tNow >= tEnd)) {
          result.success = false;
          result.error = "انتهى وقت التصويت!";
          break;
        }

        const targetCell = statusSheet.getRange(2, 3 + pId);
        const existingValue = targetCell.getValue();

        if (existingValue === "" || existingValue === null || existingValue === undefined) {
          targetCell.setValue(ans);
          result.message = "تم تسجيل الإجابة وقفلها";
        } else {
          result.success = false;
          result.error = "لا يمكنك تغيير إجابتك";
        }
        break;

      case 'nextQuestion':
        updateQuestion(statusSheet, 1);
        break;

      case 'prevQuestion':
        updateQuestion(statusSheet, -1);
        break;

      case 'toggleVoting':
        const currentV = statusSheet.getRange(2, 2).getValue();
        const willOpen = !(String(currentV).toUpperCase() === 'TRUE');

        if (willOpen) {
          const endTime = new Date().getTime() + 12000; // 12 ثانية من الآن
          statusSheet.getRange(2, 2).setValue('TRUE');
          statusSheet.getRange(2, 12).setValue(endTime.toString());
        } else {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue('0');
        }
        break;
    }
  } catch (err) {
    result.success = false;
    result.error = err.toString();
  }

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

