        // لا نقبل إجابات إذا اللعبة لم تبدأ
        if (isGameStarted && String(currentStatusData[1]).toUpperCase() === 'TRUE') {
          const targetCell = statusSheet.getRange(2, 3 + pId);
          if (targetCell.getValue() === "") targetCell.setValue(ans);
        }
        break;

      case 'toggleVoting':
        const vState = String(statusSheet.getRange(2, 2).getValue()).toUpperCase();
        if (vState !== 'TRUE') {
          statusSheet.getRange(2, 2).setValue('TRUE');
          statusSheet.getRange(2, 12).setValue(now + 12500);
        } else {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'setGameStatus':
        // تغيير حالة بدء اللعبة
        const started = String(e.parameter.started).toUpperCase(); // 'TRUE' or 'FALSE'
        statusSheet.getRange(2, 13).setValue(started);
        // عند إيقاف اللعبة، نوقف التصويت أيضاً
        if (started === 'FALSE') {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'nextQuestion':
        moveQ(statusSheet, 1);
        break;
      case 'prevQuestion':
        moveQ(statusSheet, -1);
        break;
    }
  } catch (err) {
    result.success = false;
    result.error = err.toString();
  }
  return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
}

function moveQ(sheet, d) {
  const currentId = parseInt(sheet.getRange(2, 1).getValue()) || 1;
  sheet.getRange(2, 1).setValue(Math.max(1, currentId + d));
  sheet.getRange(2, 2).setValue('FALSE');
  sheet.getRange(2, 12).setValue(0);
  sheet.getRange(2, 4, 1, 8).clearContent();
}

/**
 * كود Google Apps Script المحدث v3.1 - إصلاحات الاستقرار
 */

const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();

function doGet(e) {
  const action = e.parameter.action;
  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const statusSheet = ss.getSheetByName('Status');
  const questionsSheet = ss.getSheetByName('Questions');

  if (!statusSheet || !questionsSheet) {
     return ContentService.createTextOutput(JSON.stringify({success:false, error:"Sheet names must be 'Status' and 'Questions'"}))
    .setMimeType(ContentService.MimeType.JSON);
  }

  // التأكد من وجود صف العناوين والبيانات الأولية (للملفات الجديدة)
  if (statusSheet.getLastRow() === 0) {
    statusSheet.appendRow(['QuestionID', 'VotingOpen', 'ShowAnswer', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8', 'TimerEnd', 'GameStarted']);
    statusSheet.appendRow([1, 'FALSE', 'FALSE', '', '', '', '', '', '', '', '', '0', 'FALSE']);
  }

  const now = new Date().getTime();
  let result = { success: true, serverTime: now };

  try {
    switch(action) {
      case 'getStatus':
        // --- إصلاح للملفات القديمة ---
        // التأكد من وجود العمود 13 (GameStarted) لتجنب توقف النظام
        // نقوم بالتحقق مما إذا كان العمود 13 فارغاً في الصف 1 (العنوان)، إذا كان كذلك نقوم بتهيئته
        // استخدام getMaxColumns للتحقق من أبعاد الشبكة لتجنب الخطأ
        if (statusSheet.getMaxColumns() < 13 || statusSheet.getRange(1, 13).getValue() === "") {
             // توسيع النطاق إذا لزم الأمر وكتابة القيم الافتراضية
             statusSheet.getRange(1, 13).setValue("GameStarted");
             if (statusSheet.getRange(2, 13).getValue() === "") {
                statusSheet.getRange(2, 13).setValue("FALSE");
             }
        }

        // الآن يمكننا القراءة بأمان
        let statusData = statusSheet.getRange(2, 1, 1, 13).getValues()[0];
        let qId = parseInt(statusData[0]) || 1;
        let isVotingOpen = String(statusData[1]).toUpperCase() === 'TRUE';
        let timerEnd = Number(statusData[11]) || 0;
        let gameStarted = String(statusData[12] || "").toUpperCase() === 'TRUE';

        if (isVotingOpen && timerEnd > 0 && now >= timerEnd) {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
          isVotingOpen = false;
          timerEnd = 0;
        }

        const lastRow = Math.max(questionsSheet.getLastRow(), 1);
        const totalQuestions = Math.max(0, lastRow - 1);

        // استخدام getDataRange للحصول على البيانات المتاحة فقط لتجنب الأخطاء إذا كانت الأعمدة ناقصة في ورقة الأسئلة
        // لكننا نحتاج للتأكد من قراءة 6 أعمدة على الأقل
        let questionObj = null;
        let correctAnswer = null;

        // قراءة صف السؤال المحدد فقط بدلاً من قراءة كل الأسئلة (تحسين الأداء)
        let questionRowIndex = qId + 1; // الصف في الشيت (بدءاً من 1)

        if (questionRowIndex <= lastRow && questionRowIndex > 1) {
           // نتحقق من عدد الأعمدة في ورقة الأسئلة
           let maxCols = questionsSheet.getMaxColumns();
           let readCols = Math.min(maxCols, 6);

           if (readCols > 0) {
             let rowData = questionsSheet.getRange(questionRowIndex, 1, 1, readCols).getValues()[0];
             // تعبئة البيانات الناقصة إذا كانت الأعمدة أقل من 6
             while(rowData.length < 6) rowData.push("");

             correctAnswer = String(rowData[5] || "").trim().toUpperCase();
             questionObj = {
               id: qId,
               text: rowData[0], a: rowData[1], b: rowData[2], c: rowData[3], d: rowData[4], 
               correct: correctAnswer
             };
           }
        }

        result.data = {
          status: {
            currentQuestionId: qId,
            totalQuestions: totalQuestions,
            isVotingOpen: isVotingOpen,
            playerAnswers: statusData.slice(3, 11).map(a => String(a || "").trim().toUpperCase()),
            timerEnd: timerEnd,
            correctAnswer: correctAnswer,
            gameStarted: gameStarted
          },
          question: questionObj
        };
        break;

      case 'submitAnswer':
        const pId = parseInt(e.parameter.playerId);
        const ans = String(e.parameter.answer).trim().toUpperCase();
        // قراءة القيم الضرورية فقط للتحقق
        const checkRange = statusSheet.getRange(2, 1, 1, 13).getValues()[0];
        const isGameStartedSubmit = String(checkRange[12] || "").toUpperCase() === 'TRUE';
        const isVotingOpenSubmit = String(checkRange[1]).toUpperCase() === 'TRUE';

        if (isGameStartedSubmit && isVotingOpenSubmit) {
          const targetCell = statusSheet.getRange(2, 3 + pId);
          if (targetCell.getValue() === "") targetCell.setValue(ans);
        }
        break;

      case 'toggleVoting':
        const vStateRange = statusSheet.getRange(2, 2);
        const vState = String(vStateRange.getValue()).toUpperCase();
        if (vState !== 'TRUE') {
          vStateRange.setValue('TRUE');
          statusSheet.getRange(2, 12).setValue(now + 12500);
        } else {
          vStateRange.setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'setGameStatus':
        const started = String(e.parameter.started).toUpperCase();
        // التأكد من وجود الخلية قبل الكتابة
        if (statusSheet.getMaxColumns() < 13) statusSheet.getRange(1, 13).setValue("GameStarted");

        statusSheet.getRange(2, 13).setValue(started);
        if (started === 'FALSE') {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'nextQuestion':
        moveQ(statusSheet, 1);
        break;
      case 'prevQuestion':
        moveQ(statusSheet, -1);
        break;
    }
  } catch (err) {
    result.success = false;
    result.error = err.toString();
  }
  return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
}

function moveQ(sheet, d) {
  const currentId = parseInt(sheet.getRange(2, 1).getValue()) || 1;
  sheet.getRange(2, 1).setValue(Math.max(1, currentId + d));
  sheet.getRange(2, 2).setValue('FALSE');
  sheet.getRange(2, 12).setValue(0);
  // مسح الإجابات (P1-P8)
  sheet.getRange(2, 4, 1, 8).clearContent();
}

