في apps script قمت مع gemini chat بتطوير الاكسل او الشيت بحيث عندما يجيب المتسابقون على السؤال يضيف الاكسل 10 نقاط للجواب الصحيح ويرسل هذه الرسالة الى فيميكس ليقوم بالانميشن واضافة النقاط 
سألصق السكريبت هنا وحاول ان لا تؤثر على عمله فهو يعمل بكفاءة وتنسجم تحتيثاتك هذه معه

function doGet(e) {
  return updateScores();
}

function updateScores() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Status");

  // --- نظام القفل لمنع التكرار ---
  // نقرأ رقم السؤال الحالي من A2
  var currentQID = sheet.getRange("A2").getValue(); 
  // نقرأ رقم آخر سؤال تم حسابه من P1 (تأكد أن P1 فارغة في البداية)
  var lastCalcID = sheet.getRange("P1").getValue(); 

  // إذا كان الرقم هو نفسه، توقف فوراً ولا تفعل شيئاً
  if (currentQID == lastCalcID && currentQID !== "") {
    return ContentService.createTextOutput("Already Calculated - No Points Added");
  }
  // -----------------------------

  // قراءة الإجابة الصحيحة
  var correctAns = sheet.getRange("N2").getValue().toString().trim().toUpperCase();

  // قراءة إجابات اللاعبين
  var playerAnswers = sheet.getRange("D2:K2").getValues()[0];

  // قراءة النقاط الحالية (الخانات الزرقاء)
  var scoreRange = sheet.getRange("D5:K5");
  var currentScores = scoreRange.getValues()[0];

  var newScores = [];

  // عملية الجمع
  for (var i = 0; i < 8; i++) {
    var pAns = playerAnswers[i].toString().trim().toUpperCase();
    var currentScore = Number(currentScores[i]);

    // إذا الإجابة صحيحة
    if (pAns === correctAns && correctAns !== "") {
      newScores.push(currentScore + 10);
    } else {
      newScores.push(currentScore);
    }
  }

  // حفظ النقاط الجديدة
  scoreRange.setValues([newScores]);

  // تحديث القفل: نسجل في P1 أننا انتهينا من هذا السؤال
  sheet.getRange("P1").setValue(currentQID);

  return ContentService.createTextOutput("Success: Points Added");
}

