             while (statusSheet.getLastRow() < 5) statusSheet.appendRow(['', '', '', 0, 0, 0, 0, 0, 0, 0, 0]);
             statusSheet.getRange("C5").setValue("Scores:");
        }
        let currentScores = statusSheet.getRange("D5:K5").getValues()[0];

        result.data = {
          status: {
            currentQuestionId: qId,
            totalQuestions: totalQuestions,
            isVotingOpen: isVotingOpen,
            playerAnswers: statusData.slice(3, 11).map(a => String(a || "").trim().toUpperCase()),
            timerEnd: timerEnd,
            correctAnswer: correctAnswer,
            gameStarted: gameStarted,
            scores: currentScores
          },
          question: questionObj
        };
        break;

      case 'submitAnswer':
        const pId = parseInt(e.parameter.playerId);
        const ans = String(e.parameter.answer).trim().toUpperCase();
        // التحقق بأمان من حالة اللعبة
        if (statusSheet.getMaxColumns() >= 13) {
            const checkRange = statusSheet.getRange(2, 1, 1, 13).getValues()[0];
            const isGameStartedSubmit = String(checkRange[12] || "").toUpperCase() === 'TRUE';
            const isVotingOpenSubmit = String(checkRange[1]).toUpperCase() === 'TRUE';

            if (isGameStartedSubmit && isVotingOpenSubmit) {
              const targetCell = statusSheet.getRange(2, 3 + pId);
              if (targetCell.getValue() === "") targetCell.setValue(ans);
            }
        }
        break;

      case 'toggleVoting':
        const vStateRange = statusSheet.getRange(2, 2);
        const vState = String(vStateRange.getValue()).toUpperCase();
        if (vState !== 'TRUE') {
          vStateRange.setValue('TRUE');
          statusSheet.getRange(2, 12).setValue(now + 12500);
        } else {
          vStateRange.setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'setGameStatus':
        const started = String(e.parameter.started).toUpperCase();
        // ضمان وجود العمود قبل الكتابة
        if (statusSheet.getMaxColumns() < 13) statusSheet.insertColumnAfter(statusSheet.getMaxColumns());
        if (statusSheet.getRange(1, 13).getValue() === "") statusSheet.getRange(1, 13).setValue("GameStarted");

        statusSheet.getRange(2, 13).setValue(started);
        if (started === 'FALSE') {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'updateScores':
         updateScores(false); 
         result.message = "Calculated";
         break;

      case 'nextQuestion':
        moveQ(statusSheet, 1);
        break;
      case 'prevQuestion':
        moveQ(statusSheet, -1);
        break;
    }
  } catch (err) {
    result.success = false;
    result.error = err.toString();
  }
  return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
}

function moveQ(sheet, d) {
