/**
 * دالة احتساب النقاط الذكية
 * Smart Scoring Logic v2
 */
function updateScores(isTextOutput) {
  var ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  var sheet = ss.getSheetByName("Status");
  var questionsSheet = ss.getSheetByName("Questions");

  if (!sheet || !questionsSheet) {
      if (isTextOutput) return ContentService.createTextOutput("Error: Sheets not found");
      return;
  }

  // 1. مزامنة الإجابة الصحيحة
  var currentQID = sheet.getRange("A2").getValue();
  if (currentQID && typeof currentQID === 'number') {
      var lastRow = questionsSheet.getLastRow();
      if (currentQID + 1 <= lastRow) {
         var realCorrectAns = questionsSheet.getRange(currentQID + 1, 6).getValue();
         sheet.getRange("N2").setValue(realCorrectAns);
      }
  }

  // --- نظام القفل الذكي (Smart Lock) ---
  // نقرأ الخلية P1. سابقاً كانت تحتوي على رقم السؤال فقط.
  // الآن ستحتوي على: "QuestionID|PlayerIndex1,PlayerIndex2,..."
  // مثال: "5|0,6" تعني السؤال الخامس تم احتسابه للاعب الأول واللاعب السابع

  var lockDataRaw = String(sheet.getRange("P1").getValue());
  var lockData = lockDataRaw.split("|");
  var lastCalcID = lockData[0];
  var creditedPlayers = []; // مصفوفة لتخزين من حصلوا على نقاط لهذا السؤال

  // إذا كان نفس السؤال، نسترجع قائمة اللاعبين المحتسب لهم
  if (lastCalcID === String(currentQID) && lockData.length > 1 && lockData[1] !== "") {
      creditedPlayers = lockData[1].split(",");
  } else if (lastCalcID !== String(currentQID)) {
      // إذا تغير السؤال ولم يتم تصفير P1 لسبب ما، نبدأ من جديد
      creditedPlayers = [];
  }

  var correctAns = String(sheet.getRange("N2").getValue()).trim().toUpperCase();
  var playerAnswers = sheet.getRange("D2:K2").getValues()[0];

  // التأكد من وجود صفوف النقاط
  if (sheet.getLastRow() < 5) {
     while (sheet.getLastRow() < 5) sheet.appendRow(['', '', '', 0, 0, 0, 0, 0, 0, 0, 0]);
  }

  var scoreRange = sheet.getRange("D5:K5");
  var currentScores = scoreRange.getValues()[0];
  var newScores = [];
  var pointsAdded = false;

  for (var i = 0; i < 8; i++) {
    var pAns = String(playerAnswers[i] || "").trim().toUpperCase();
    var currentScore = Number(currentScores[i]) || 0;

    // الشرط: الإجابة صحيحة + الإجابة موجودة + اللاعب لم يحصل على نقاط لهذا السؤال من قبل
    if (pAns === correctAns && correctAns !== "") {
        if (!creditedPlayers.includes(String(i))) {
            newScores.push(currentScore + 10);
            creditedPlayers.push(String(i)); // إضافة اللاعب للقائمة
            pointsAdded = true;
        } else {
            // اللاعب حصل على نقاط سابقاً، لا نضيف له مرة أخرى
            newScores.push(currentScore);
        }
    } else {
      newScores.push(currentScore);
    }
  }

  if (pointsAdded) {
      scoreRange.setValues([newScores]);
      // تحديث القفل بالقائمة الجديدة
      sheet.getRange("P1").setValue(currentQID + "|" + creditedPlayers.join(","));
      if (isTextOutput) return ContentService.createTextOutput("Success: Points Added for new winners");
  } else {
      if (isTextOutput) return ContentService.createTextOutput("No new points to add (All correct players already credited)");
  }
}

