        statusSheet.getRange(2, 13).setValue(started);
        if (started === 'FALSE') {
          statusSheet.getRange(2, 2).setValue('FALSE');
          statusSheet.getRange(2, 12).setValue(0);
        }
        break;

      case 'nextQuestion':
        moveQ(statusSheet, 1);
        break;
      case 'prevQuestion':
        moveQ(statusSheet, -1);
        break;

      case 'updateScores':
        // هذا للأزرار القديمة (التي تحسب للفقرة 1)
        const scoresResult = handleUpdateScores(false);
        result.message = scoresResult.getContent();
        // -- إضافة: عند تحديث نقاط الفقرة 1، نقوم بمزامنتها مع ورقة التحكم الجديدة أيضاً
        syncSeg1ToControl(statusSheet, controlSheet);
        break;

      // ============================================================
