/**
 * MISHKAH v5.0 - Live View Management
 * يدعم تغيير العرض على الشاشة (تصفير أو مجموع)
 */

const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();

function doGet(e) {
  if (!e || !e.parameter || !e.parameter.action) return ContentService.createTextOutput("Mishkah API Ready");

  const action = e.parameter.action;
  ensureGameControlSheet(); 

  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const statusSheet = ss.getSheetByName('Status');
  const controlSheet = ss.getSheetByName('GameControl');

  let result = { success: true };

  try {
    switch(action) {
      // --- أوامر التحكم في العرض (ماذا يظهر في vMix) ---
      case 'setView':
        var view = e.parameter.view; // seg1, seg2, seg3, seg4, seg5, total
        updateLiveRow(controlSheet, view);
        result.msg = "View switched to: " + view;
        break;

      // --- أوامر إضافة النقاط (مع تحديث العرض تلقائياً) ---
      case 'addSeg2': // مثال للفقرات اليدوية
        var pId = parseInt(e.parameter.playerId) - 1;
        var cell = controlSheet.getRange(3, 2 + pId); // صف الفقرة 2
        cell.setValue(Number(cell.getValue()) + 20);
        updateTotals(controlSheet);
        // نحدث صف العرض ليعكس التغيير فوراً
        updateLiveRow(controlSheet, 'seg2'); 
        result.msg = "P" + (pId+1) + " +20";
        break;

      case 'addSeg3':
        var pId = parseInt(e.parameter.playerId) - 1;
        var cell = controlSheet.getRange(4, 2 + pId);
        cell.setValue(Number(cell.getValue()) + 10);
        var cnt = controlSheet.getRange(5, 2 + pId);
        cnt.setValue(Number(cnt.getValue()) + 1);
        if (Number(cnt.getValue()) === 7) controlSheet.getRange(6, 2 + pId).setValue(5);
        updateTotals(controlSheet);
        updateLiveRow(controlSheet, 'seg3');
        break;

      case 'addSeg4':
        var pId = parseInt(e.parameter.playerId) - 1;
        var cell = controlSheet.getRange(7, 2 + pId);
        cell.setValue(Number(cell.getValue()) + 25);
        updateTotals(controlSheet);
        updateLiveRow(controlSheet, 'seg4');
        break;

      case 'addSeg5':
        var pId = parseInt(e.parameter.playerId) - 1;
        var pts = parseInt(e.parameter.points);
        var cell = controlSheet.getRange(10, 2 + pId);
        cell.setValue(Number(cell.getValue()) + pts);
        updateLiveRow(controlSheet, 'seg5');
        break;

      // --- الأوامر القديمة (Status etc..) ---
      // (بقيت كما هي، تم اختصارها هنا للتركيز، لكن انسخ الدوال المساعدة بالأسفل)
      case 'syncSeg1':
        syncSeg1ToControl(statusSheet, controlSheet);
        updateLiveRow(controlSheet, 'seg1');
        break;

      // ... (باقي الأكواد القديمة getStatus, submitAnswer تبقى كما هي في الكود السابق v4.2) ...
    }
  } catch (err) {
    result.error = err.toString();
  }

  return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
}

// --- الدالة السحرية الجديدة: تحديث صف البث المباشر ---
function updateLiveRow(sheet, viewMode) {
  // سنخصص الصف رقم 12 ليكون هو "LIVE DISPLAY" الذي يقرأ منه vMix
  // العناوين في A12
  sheet.getRange("A12").setValue("LIVE SCREEN (" + viewMode + ")").setBackground("#00ff00");

  var sourceRow = 2; // افتراضياً الفقرة 1

  if (viewMode == 'seg1') sourceRow = 2;
  else if (viewMode == 'seg2') sourceRow = 3;
  else if (viewMode == 'seg3') sourceRow = 4; // (يجب تعديل الكود لجمع البونص للعرض)
  else if (viewMode == 'seg4') sourceRow = 7;
  else if (viewMode == 'total') sourceRow = 8; // المجموع الكلي
  else if (viewMode == 'seg5') sourceRow = 10;

  // نسخ القيم من الصف المطلوب إلى الصف 12
  for (var i = 0; i < 8; i++) {
    var val = sheet.getRange(sourceRow, 2 + i).getValue();
    // حالة خاصة للفقرة 3 لجمع البونص في العرض
    if (viewMode == 'seg3') {
       val = Number(val) + Number(sheet.getRange(6, 2 + i).getValue());
    }
    sheet.getRange(12, 2 + i).setValue(val);
  }
}

// --- الدوال المساعدة الضرورية (نسخ ولصق من الكود السابق) ---
function ensureGameControlSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('GameControl');
  if (!sheet) sheet = ss.insertSheet('GameControl');
  // ... (نفس كود التنسيق السابق) ...
  // تأكد من تهيئة الصف 12
  sheet.getRange("A12").setValue("LIVE SCREEN").setFontWeight("bold");
}

function updateTotals(sheet) {
  // (نفس كود الجمع السابق)
  for (var col = 2; col <= 9; col++) {
    var total = 0;
    total += Number(sheet.getRange(2, col).getValue()) || 0; // Seg1
    total += Number(sheet.getRange(3, col).getValue()) || 0; // Seg2
    total += Number(sheet.getRange(4, col).getValue()) || 0; // Seg3
    total += Number(sheet.getRange(6, col).getValue()) || 0; // Seg3 Bonus
    total += Number(sheet.getRange(7, col).getValue()) || 0; // Seg4
    sheet.getRange(8, col).setValue(total);
  }
}

function syncSeg1ToControl(statusSheet, controlSheet) {
    var seg1Scores = statusSheet.getRange("D5:K5").getValues()[0];
    controlSheet.getRange(2, 2, 1, 8).setValues([seg1Scores]);
    updateTotals(controlSheet);
}
