        updateLiveRow(controlSheet, 'seg2'); // Auto-switch view
        result.msg = "P" + (pId2+1) + " +20 (Seg2)";
        break;

      case 'addSeg3':
        var pId3 = parseInt(e.parameter.playerId) - 1;
